def _build_extended_service_specs() -> tuple[ServiceSpec, ...]:
    specs: list[ServiceSpec] = []
    for base_slug, base_title, category, summary, steps, benefits, tags, source_kind in _EXTENDED_SERVICE_BASES:
        for scope_slug, scope_title, scope_noun, scope_factor in _SERVICE_VARIANT_SCOPES:
            specs.append(
                ServiceSpec(
                    slug=f"{base_slug}-{scope_slug}",
                    title=f"{base_title} {scope_title}",
                    category=category,
                    summary=f"{summary} تُكيّف الخطة مع {scope_noun} مع مراعاة {scope_factor}.",
                    steps=(steps[0], steps[1], steps[2], f"{steps[3]} مع مراجعة متطلبات {scope_noun}"),
                    benefits=(benefits[0], benefits[1], f"حل مناسب لطبيعة {scope_noun}"),
                    tags=(*tags, scope_title.replace("لـ", "").strip()),
                    source_kind=source_kind,
                )
            )
    return tuple(specs)


EXTENDED_SERVICE_SPECS = _build_extended_service_specs()
ALL_SERVICE_SPECS = SERVICE_SPECS + EXTENDED_SERVICE_SPECS

